function applyAnonymousModeOptions() {
  const anonMode = Boolean(document.getElementById('anonModeToggle')?.checked);
  const anonProxy = Boolean(document.getElementById('anonProxychainsToggle')?.checked);
  const anonIdentityRotation = Boolean(document.getElementById('anonIdentityRotationToggle')?.checked);
  const wrap = document.getElementById('anonModeWrap');
  if (wrap) wrap.style.display = anonMode ? 'block' : 'none';
  const modProxy = document.getElementById('modKaliProxychains');
  const modIdentity = document.getElementById('modIdentityRotation');
  const kaliMode = document.getElementById('kaliModeToggle');
  if (!anonMode) {
    if (modProxy) setInputChecked(modProxy.id, false);
    if (modIdentity) setInputChecked(modIdentity.id, false);
    return;
  }
  if (modProxy) setInputChecked(modProxy.id, anonProxy);
  if (modIdentity) setInputChecked(modIdentity.id, anonIdentityRotation);
  const anonTor = Boolean(document.getElementById('anonTorToggle')?.checked);
  if ((anonTor || anonProxy) && kaliMode && !kaliMode.checked && !kaliMode.disabled) kaliMode.checked = true;
}

